Item.method_code:
    // 新規作成時は設定画面を表示するため処理なし
    const itemId = document.thisItem.getProperty('id');
    if (typeof itemId === 'undefined' || itemId == '') {
        return;
    }
    
    const accordions = parent.document.getElementsByClassName("aras-accordion");
    if (accordions && accordions.length > 0) {
        accordions[0].toggle(true);  // true: Close
    }

    return;
